def filter_hmm(model, observations, dates=None):
    """Forward filtering on the daily calendar, with frozen training parameters."""
    from scipy.stats import multivariate_normal

    observations = np.asarray(observations, dtype=float)
    if observations.ndim != 2 or observations.shape[1] != 2 or not len(observations):
        raise ValueError("Input HMM harus berupa matriks return dan volatilitas.")
    dates = pd.DatetimeIndex(dates) if dates is not None else pd.date_range("2000-01-01", periods=len(observations))
    if len(dates) != len(observations) or not dates.is_unique or not dates.is_monotonic_increasing:
        raise ValueError("Kalender filtering HMM tidak valid.")
    result = np.full((len(observations), model.n_components), np.nan)
    posterior, last_date = None, None
    for i, (date, observation) in enumerate(zip(dates, observations)):
        if posterior is not None and last_date is not None:
            for _ in range((date-last_date).days):
                posterior = posterior @ model.transmat_
        if np.isfinite(observation).all():
            prior = model.startprob_.copy() if posterior is None else posterior
            emission = np.array([multivariate_normal.logpdf(observation, mean=model.means_[j],
                cov=model.covars_[j], allow_singular=True) for j in range(model.n_components)])
            score = np.log(np.maximum(prior, np.finfo(float).tiny)) + emission
            posterior = np.exp(score-logsumexp(score))
            result[i] = posterior
        last_date = date
    valid = np.isfinite(result).all(axis=1)
    if not valid.any() or not np.allclose(result[valid].sum(axis=1), 1, atol=1e-8):
        raise ValueError("Probabilitas filtering HMM tidak valid.")
    return result


def map_train_states(model, train_observations=None):
    """Rank the fitted emission return means, as specified in Bab III."""
    return {int(state): int(rank) for rank, state in enumerate(np.argsort(model.means_[:, 0]))}


def split_forecast_frame(frame):
    """Chronological floor(70%)/floor(80%) boundaries; no extra purge."""
    n = len(frame)
    train_end, calib_end = int(n * .70), int(n * .80)
    if train_end < 60 or calib_end - train_end < 20 or n - calib_end < 20:
        raise ValueError("Data lengkap belum cukup untuk train, kalibrasi, dan test.")
    train = frame.iloc[:train_end].copy()
    calibration = frame.iloc[train_end:calib_end].copy()
    test = frame.iloc[calib_end:].copy()
    if not (train.target_date.max() < calibration.target_date.min()
            and calibration.target_date.max() < test.target_date.min()
            and train.target_date.max() <= calibration.index.min()
            and calibration.target_date.max() <= test.index.min()):
        raise ValueError("Tanggal target melintasi batas split.")
    return train, calibration, test


def conformal_margin(scores, alpha=.10):
    """Finite-sample order statistic ceil((n+1)*(1-alpha)), without interpolation."""
    scores = np.asarray(scores, dtype=float)
    if not len(scores) or not np.isfinite(scores).all() or not 0 < alpha < 1:
        raise ValueError("Skor kalibrasi tidak valid.")
    k = int(np.ceil((len(scores)+1)*(1-alpha)))
    if k > len(scores):
        raise ValueError("Sampel kalibrasi tidak cukup untuk tingkat cakupan yang diminta.")
    return float(np.partition(scores, k-1)[k-1])


def load_experiments():
    """Decode verified Google Colab TA results and real fallback snapshots; no network or training."""
    raw = zlib.decompress(base64.b64decode(_EXPERIMENTS_B64, validate=True))
    if hashlib.sha256(raw).hexdigest() != _EXPERIMENTS_SHA256:
        raise ValueError("Integritas data eksperimen tertanam tidak sesuai.")
    data = json.loads(raw)
    if data.get("schema_version") != 3 or "colab_latest" not in data.get("runs", {}):
        raise ValueError("Paket hasil eksperimen tidak valid.")
    primary = data['runs']['colab_latest']
    if (set(data['runs']) != {'colab_latest'} or primary.get('run_id') != REFERENCE_RUN_ID
            or primary.get('execution_context') != 'google_colab'
            or primary.get('status') != 'completed' or not primary.get('reference_for_manuscript')
            or primary.get('validation', {}).get('status') != 'passed'):
        raise ValueError('Identitas hasil berbeda dari run Colab rujukan naskah.')
    for run in data["runs"].values():
        names = {row["Model"] for row in run["metrics"]}
        if names != set(BASELINES + ['Tanpa HMM', 'Tanpa interaksi']) or len(names) != len(run["metrics"]):
            raise ValueError("Identitas model pada paket hasil tidak valid.")
        for row in run["metrics"]:
            if (not all(np.isfinite(row[key]) for key in ['MAE', 'RMSE', 'MAPE', 'R2', 'DirAcc'])
                    or row["n"] != run["n"]):
                raise ValueError("Metrik atau ukuran sampel tidak valid.")
        for row in run["statistics"]:
            if row["n"] != run["n"]:
                raise ValueError("Ukuran sampel statistik berbeda dari metrik.")
            if (row["block"] not in [7, 14, 30] or row["ci_low"] > row["ci_high"]
                    or not all(np.isfinite(row[key]) for key in ['difference', 'ci_low', 'ci_high'])):
                raise ValueError("Interval bootstrap tidak valid.")
    for snapshot in data['snapshots'].values():
        if (snapshot.get('run_id') != REFERENCE_RUN_ID
                or hashlib.sha256(snapshot['csv'].encode('utf-8')).hexdigest() != snapshot['csv_sha256']):
            raise ValueError('Snapshot cadangan tidak sesuai dengan run Colab rujukan.')
    return data


def prepare_daily(prices, sentiment, onchain, fill_sources=False):
    """Keep the daily calendar; separate actual records from operational filling."""
    for label, frame, column in [('harga', prices, 'close'), ('sentimen', sentiment, 'polarity'),
                                 ('on-chain', onchain, 'exchange_netflow')]:
        if (frame.empty or column not in frame or not isinstance(frame.index, pd.DatetimeIndex)
                or not frame.index.is_unique or not frame.index.is_monotonic_increasing):
            raise ValueError(f"Tanggal atau kolom sumber {label} tidak valid.")
        if frame.index.tz is not None or (frame.index != frame.index.normalize()).any():
            raise ValueError(f"Tanggal sumber {label} harus berupa hari UTC yang dinormalisasi.")
    dates = pd.date_range(prices.index.min(), prices.index.max(), freq='D')
    df = prices[['close']].reindex(dates).join(sentiment[['polarity']], how='left')
    df = df.join(onchain[['exchange_netflow']], how='left')
    for column in ['value', 'value_classification']:
        if column in sentiment:
            df[column] = sentiment[column].reindex(dates)
    for field, name in [('polarity', 'sentiment'), ('exchange_netflow', 'onchain')]:
        observed = df[field].notna()
        source_dates = pd.Series(dates, index=dates).where(observed).ffill()
        df[f'{name}_observation_date'] = source_dates
        if fill_sources:
            df[field] = df[field].ffill()
        df[f'{name}_imputed'] = (~observed) & df[field].notna()
    if fill_sources:
        for column in ['value', 'value_classification']:
            if column in df:
                df[column] = df[column].ffill()
    if (df.close <= 0).any():
        raise ValueError("Harga harus positif.")
    for column in ['close', 'polarity', 'exchange_netflow']:
        if not np.isfinite(df[column].dropna().to_numpy(dtype=float)).all():
            raise ValueError(f"Nilai {column} tidak finite.")
    if not df.polarity.dropna().between(-1, 1).all():
        raise ValueError("Polaritas harus berada pada rentang -1 sampai 1.")
    df["log_return"] = np.log(df.close / df.close.shift(1))
    for days in [7, 14, 30]:
        df[f"volatility_{days}d"] = df.log_return.rolling(days, min_periods=days).std(ddof=1)
    for days in [7, 30]:
        df[f"price_to_ma{days}"] = df.close / df.close.rolling(days).mean()
    for lag in [1, 2, 3]:
        df[f"return_lag_{lag}"] = df.log_return.shift(lag)
    df["netflow_change"] = df.exchange_netflow.diff()
    df["netflow_ma_7"] = df.exchange_netflow.rolling(7).mean()
    df["sentiment_ma_7"] = df.polarity.rolling(7).mean()
    df["netflow_weighted"] = df.exchange_netflow * (1 + df.polarity)
    df["target_return"] = np.log(df.close.shift(-1)/df.close)
    df["target_date"] = df.index + pd.Timedelta(days=1)
    return df


def predict_sorted_quantiles(models, features):
    raw = np.column_stack([model.predict(features) for model in models])
    if not np.isfinite(raw).all():
        raise ValueError("Prediksi kuantil tidak finite.")
    crossing = (raw[:, 0] > raw[:, 1]) | (raw[:, 1] > raw[:, 2])
    return np.sort(raw, axis=1), int(crossing.sum())


def build_forecast(prices, sentiment, onchain, onchain_live=False):
    """Fit on complete real historical samples; fill only the operational inputs."""
    from importlib.metadata import version
    from hmmlearn.hmm import GaussianHMM
    from xgboost import XGBRegressor

    fit_timings = {}
    section_started = time.perf_counter()
    historical = prepare_daily(prices, sentiment, onchain, fill_sources=False)
    df = prepare_daily(prices, sentiment, onchain, fill_sources=True)
    usable = historical.dropna(subset=FEATURE_COLS[:-1]+['target_return'])
    train_base, _, _ = split_forecast_frame(usable)
    hmm_data = train_base[['log_return', 'volatility_14d']]
    segments = hmm_data.index.to_series().diff().dt.days.ne(1).cumsum()
    lengths = segments.value_counts(sort=False).tolist()
    hmm = GaussianHMM(n_components=3, covariance_type='full', n_iter=200, random_state=42)
    fit_timings["feature_preparation_seconds"] = time.perf_counter() - section_started
    section_started = time.perf_counter()
    with warnings.catch_warnings(record=True) as fit_warnings:
        warnings.simplefilter('always')
        hmm.fit(hmm_data.to_numpy(), lengths=lengths)
    if not hmm.monitor_.converged:
        raise ValueError('HMM belum konvergen; prediksi belum dapat ditampilkan.')
    fit_timings["hmm_fit_seconds"] = time.perf_counter() - section_started
    section_started = time.perf_counter()
    mapping = map_train_states(hmm)
    probabilities = filter_hmm(hmm, df[['log_return','volatility_14d']].to_numpy(), df.index)
    valid = np.isfinite(probabilities).all(axis=1)
    labels = pd.Series(np.nan, index=df.index)
    labels.loc[valid] = [mapping[int(state)] for state in probabilities[valid].argmax(axis=1)]
    df['regime_labeled'] = labels
    historical['regime_labeled'] = labels
    usable = historical.dropna(subset=FEATURE_COLS+['target_return'])
    train, calibration, test = split_forecast_frame(usable)
    live = df.iloc[[-1]]
    if not np.isfinite(live[FEATURE_COLS].to_numpy(dtype=float)).all():
        raise ValueError("Fitur prediksi terakhir tidak lengkap.")
    params = dict(n_estimators=300, learning_rate=.05, max_depth=5,
                  random_state=42, verbosity=0, tree_method="hist", n_jobs=2)
    models = [XGBRegressor(**params, objective="reg:quantileerror", quantile_alpha=q)
              for q in [.05, .50, .95]]
    fit_timings["regime_filter_and_split_seconds"] = time.perf_counter() - section_started
    train_X, train_y = train[FEATURE_COLS].astype(float), train.target_return.to_numpy()
    section_started = time.perf_counter()
    for model in models:
        model.fit(train_X, train_y)
    fit_timings["xgboost_three_fits_seconds"] = time.perf_counter() - section_started
    fit_timings["pure_fit_seconds"] = fit_timings["hmm_fit_seconds"] + fit_timings["xgboost_three_fits_seconds"]
    section_started = time.perf_counter()
    cal_q, crossing_cal = predict_sorted_quantiles(models, calibration[FEATURE_COLS].astype(float))
    scores = np.maximum(cal_q[:, 0] - calibration.target_return.to_numpy(),
                        calibration.target_return.to_numpy() - cal_q[:, 2])
    margin = conformal_margin(scores)
    live_q, crossing_live = predict_sorted_quantiles(models, live[FEATURE_COLS].astype(float))
    lo, med, hi = live_q[0]
    close = float(live.close.iloc[0])
    pred_lo, pred_med, pred_hi = close * np.exp([lo - margin, med, hi + margin])
    test_q, crossing_test = predict_sorted_quantiles(models, test[FEATURE_COLS].astype(float))
    hist_lo = test.close.to_numpy() * np.exp(test_q[:, 0]-margin)
    hist_med = test.close.to_numpy() * np.exp(test_q[:, 1])
    hist_hi = test.close.to_numpy() * np.exp(test_q[:, 2]+margin)
    if not np.isfinite([pred_lo, pred_med, pred_hi]).all() or not np.isfinite(hist_lo).all() or not np.isfinite(hist_hi).all():
        raise ValueError("Prediksi harga tidak finite.")
    empty_live = bool(pred_lo > pred_hi)
    empty_test = hist_lo > hist_hi
    hist_lo = np.where(empty_test, np.nan, hist_lo)
    hist_hi = np.where(empty_test, np.nan, hist_hi)
    fit_timings["calibration_and_prediction_seconds"] = time.perf_counter() - section_started
    history = list(hmm.monitor_.history)
    metadata = dict(version=CORE_VERSION, reference_run_id=REFERENCE_RUN_ID, forecast_context='operational_refit',
        timings=fit_timings, regime_method="forward_filter_emission_mean_rank", hmm_fit_n=len(hmm_data),
        hmm_fit_end=str(hmm_data.index[-1].date()), hmm_iterations=int(hmm.monitor_.iter),
        hmm_converged=bool(hmm.monitor_.converged), hmm_warnings=[str(w.message) for w in fit_warnings],
        state_to_label=mapping, emission_return_means=hmm.means_[:,0].tolist(),
        hmm_last_delta=float(history[-1] - history[-2]) if len(history) > 1 else None,
        train_n=len(train), calibration_n=len(calibration), test_n=len(test),
        train_end=str(train.index[-1].date()), calibration_end=str(calibration.index[-1].date()),
        train_target_end=str(train.target_date.iloc[-1].date()),
        calibration_target_end=str(calibration.target_date.iloc[-1].date()),
        test_target_start=str(test.target_date.iloc[0].date()), test_target_end=str(test.target_date.iloc[-1].date()),
        purge_days=0, quantile_method="finite_sample_order_statistic", calibration_k=int(np.ceil((len(scores)+1)*.9)),
        crossing_calibration=crossing_cal, crossing_test=crossing_test, crossing_live=crossing_live,
        empty_test_n=int(empty_test.sum()), empty_live=empty_live,
        training_sources="complete_real_only", operational_fill="forward_only_with_observation_dates",
        onchain_imputed_n=int(df.onchain_imputed.sum()), sentiment_imputed_n=int(df.sentiment_imputed.sum()),
        feature_count=len(FEATURE_COLS),
        versions={name: version(name) for name in ["numpy", "pandas", "scipy", "hmmlearn", "xgboost"]})
    last_real = live.onchain_observation_date.iloc[0]
    last_sent = live.sentiment_observation_date.iloc[0]
    return dict(df=df, df_test=test, hist_target_dates=test.target_date,
        pred_date=live.index[0] + pd.Timedelta(days=1), pred_lo=float(pred_lo), pred_med=float(pred_med),
        pred_hi=float(pred_hi), interval_empty=empty_live, last_close=close, last_date=live.index[0],
        last_regime=int(live.regime_labeled.iloc[0]), last_sent=float(live.polarity.iloc[0]),
        last_fgi=float(live['value'].iloc[0]) if 'value' in live else None,
        last_sentiment_category=str(live['value_classification'].iloc[0]) if 'value_classification' in live else None,
        sentiment_last_real_date=last_sent, sentiment_staleness_days=(live.index[0]-last_sent).days,
        last_netflow=float(live.exchange_netflow.iloc[0]), hist_lo=hist_lo, hist_med=hist_med, hist_hi=hist_hi,
        hist_true=test.close.to_numpy() * np.exp(test.target_return.to_numpy()), conf_margin=margin,
        onchain_live=onchain_live, onchain_last_real_date=last_real, onchain_last_csv_date=onchain.index.max(),
        onchain_staleness_days=(prices.index.max() - last_real).days, pipeline_metadata=metadata)

BASELINES = ["XGBoost", "LightGBM", "Random Forest", "SVR", "LSTM", "Model Usulan"]
METRICS = ["MAE", "RMSE", "MAPE", "R2", "DirAcc", "Coverage", "AvgWidth", "PinballLo", "PinballHi"]


def display_metrics(frame):
    result = frame.copy()
    for column in METRICS:
        if column not in result.columns:
            continue
        if column in ["MAE", "RMSE", "AvgWidth", "PinballLo", "PinballHi"]:
            fmt = lambda x: f"${x:,.2f}"
        elif column in ["MAPE", "DirAcc", "Coverage"]:
            fmt = lambda x: f"{x:.2f}%"
        elif column == "R2":
            fmt = lambda x: f"{x:.4f}"
        else:
            fmt = lambda x: f"{x:.2f}"
        result[column] = result[column].map(lambda x: fmt(x) if pd.notna(x) else "—")
    return result


def statistic_table(statistics):
    rows = []
    for row in statistics:
        crosses_zero = row['ci_low'] <= 0 <= row['ci_high']
        identical = row.get('same_median_predictions', False)
        interpretation = ('Median identik pada run ini' if identical else
            'Belum meyakinkan' if crosses_zero else
            'Model usulan lebih rendah' if row['ci_high'] < 0 else 'Pembanding lebih rendah')
        rows.append({"Pembanding": row["comparison"], "Metrik": row["metric"],
            "n": row["n"], "Δ FULL − pembanding": f"{row['difference']:+.4f}",
            "CI 95% persentil (USD)": f"[{row['ci_low']:+.2f}; {row['ci_high']:+.2f}]",
            "CI memuat nol": 'Ya' if crosses_zero else 'Tidak',
            "Interpretasi MAE": interpretation})
    return pd.DataFrame(rows)


def main_comparison_frame(run):
    """Six familiar model rows, always from the fixed primary experiment."""
    roles = {"XGBoost": "Gradient boosting", "LightGBM": "Gradient boosting",
             "Random Forest": "Ensemble tree", "SVR": "Support vector",
             "LSTM": "Deep learning sekuensial",
             "Model Usulan": "HMM + XGB Quantile + Conformal"}
    metrics = pd.DataFrame(run["metrics"]).set_index("Model")
    main = metrics.loc[BASELINES[:6]].reset_index()
    main.insert(0, "Peringkat MAE", main.MAE.rank(method="min", ascending=True).astype(int))
    main = main.sort_values(["MAE", "Model"], kind="stable").reset_index(drop=True)
    main.insert(2, "Peran", main.Model.map(roles))
    main.insert(3, "Sumber", run['source'])
    return main[["Peringkat MAE", "Model", "Peran", "Sumber"] + METRICS[:7]]


def selected_statistics(run, block=7):
    return statistic_table([row for row in run['statistics'] if row['block'] == block])


def render_inference_note(run, block):
    st.caption(f"Moving block bootstrap · {run['bootstrap_resamples']:,} resample · blok {block} hari · CI persentil 95%.")
    st.caption('Selisih MAE (USD) = Model Usulan (FULL) − pembanding. Nilai negatif mendukung model usulan. '
               'CI yang memuat nol bukan bukti kesetaraan. CI [0; 0] untuk median identik hanya '
               'menjelaskan kesamaan prediksi pada run ini. CI belum dikoreksi untuk banyaknya perbandingan; '
               'peluang tanda bootstrap bukan p-value formal.')


def render_ablation(run, table, render_table, suffix=""):
    metrics = pd.DataFrame(run["metrics"])
    ablation = metrics[metrics.Model.isin(["Model Usulan", "Tanpa HMM", "Tanpa interaksi"])]
    render_table(display_metrics(ablation[["Model", "n"] + METRICS]), label="Metrik ablasi" + suffix)
    render_table(table[table.Pembanding.isin(["Tanpa HMM", "Tanpa interaksi"])],
                 label="Uji ablasi" + suffix)
    st.caption('Tanpa HMM menghapus regime_labeled. Tanpa interaksi hanya menghapus netflow_weighted; '
               'netflow mentah dan polaritas sentimen tetap digunakan. Setiap varian dikalibrasi sendiri. '
               'CI tersedia untuk MAE; perbedaan coverage, arah, dan pinball dilaporkan secara deskriptif.')
    indexed = metrics.set_index('Model')
    full, no_hmm, no_interaction = [indexed.loc[name] for name in ['Model Usulan', 'Tanpa HMM', 'Tanpa interaksi']]
    if run['median_identical_without_hmm']:
        st.caption(f"Median FULL dan tanpa HMM identik pada run Colab ini; MAE keduanya ${full.MAE:,.2f}. "
                   'CI [0; 0] berasal dari kesalahan berpasangan yang sama, bukan bukti kesetaraan umum. '
                   f"Pinball Q95 FULL lebih tinggi ${full.PinballHi-no_hmm.PinballHi:,.2f}; "
                   'kesamaan median tidak berarti seluruh interval identik.')
    st.caption(f"FULL − tanpa interaksi: Δ MAE ${full.MAE-no_interaction.MAE:+,.2f}; "
               'CI memuat nol pada blok 7, 14, dan 30 hari. '
               f"Δ pinball Q05 ${full.PinballLo-no_interaction.PinballLo:+,.2f}, "
               f"Q95 ${full.PinballHi-no_interaction.PinballHi:+,.2f}. "
               'Pinball lebih kecil lebih baik; perubahan kedua ekor tidak seragam.')


def render_metric_charts(run, render_chart, accent):
    metrics = pd.DataFrame(run["metrics"])
    main = metrics[metrics.Model.isin(BASELINES)]
    st.markdown("<div class='section-label'>Visualisasi Metrik</div>", unsafe_allow_html=True)
    chart_tabs = st.tabs(["MAE & MAPE", "R² & DirAcc", "Probabilistik"])
    colors = [accent if name == "Model Usulan" else "#aab4bf" for name in main.Model]
    for chart_tab, pairs in zip(chart_tabs[:2], [
        [("MAE", "MAE (USD) · lebih rendah lebih baik", "${:,.2f}"), ("MAPE", "MAPE (%)", "{:.2f}%")],
        [("R2", "R²", "{:.4f}"), ("DirAcc", "Directional Accuracy (%)", "{:.2f}%")],
    ]):
        with chart_tab:
            columns = st.columns(2)
            for column, (metric, title, fmt) in zip(columns, pairs):
                with column:
                    fig = go.Figure(go.Bar(y=main.Model, x=main[metric], orientation="h", marker_color=colors,
                        text=[fmt.format(v) for v in main[metric]], textposition="outside"))
                    fig.update_layout(title=title, height=350, margin=dict(r=90))
                    if metric == "DirAcc":
                        fig.add_vline(x=50, line_dash="dash", line_color="#637080")
                    render_chart(fig)
    with chart_tabs[2]:
        full = metrics[metrics.Model.eq("Model Usulan")].iloc[0]
        for column, metric, label in zip(st.columns(4), ["Coverage", "AvgWidth", "PinballLo", "PinballHi"],
                                          ["Coverage", "Avg Width", "Pinball Q05", "Pinball Q95"]):
            value = f"{full[metric]:.2f}%" if metric == "Coverage" else f"${full[metric]:,.2f}"
            column.metric(label, value)
        st.caption("Coverage empiris pada eksperimen utama; target nominal 90%. Ini tidak menjamin cakupan live "
                   "atau cakupan sama pada setiap periode, khususnya ketika netflow tertinggal.")
        before_after = pd.DataFrame(run['intervals'])
        before_after = before_after[before_after.variant.eq('FULL')].copy()
        before_after['Tahap'] = before_after.stage.map({'raw':'Sebelum conformal', 'conformal':'Sesudah conformal'})
        before_after = before_after.rename(columns={'coverage_pct':'Coverage','width_USD':'AvgWidth',
            'pinball_05_USD':'PinballLo','pinball_95_USD':'PinballHi'})
        render_table(display_metrics(before_after[['Tahap','Coverage','AvgWidth','PinballLo','PinballHi']]),
                     label='Interval sebelum dan sesudah conformal')
        st.caption('Pinball Q05/Q95 dihitung dalam USD dari kuantil mentah setelah pengurutan, sebelum conformal. '
                   'Nilainya sama pada kedua tahap karena kuantil yang dinilai tetap sama. Coverage yang lebih tinggi '
                   'dibaca bersama jarak terhadap target 90% dan lebar interval.')
        raw, calibrated = [before_after[before_after.stage.eq(stage)].iloc[0] for stage in ['raw', 'conformal']]
        st.caption(f"Cakupan berubah dari {run['raw_covered_n']}/{run['n']} ({raw.Coverage:.2f}%) "
                   f"menjadi {run['covered_n']}/{run['n']} ({calibrated.Coverage:.2f}%). "
                   f"Jarak terhadap nominal 90% berkurang dari {abs(raw.Coverage-90):.2f} "
                   f"menjadi {abs(calibrated.Coverage-90):.2f} poin persentase, "
                   f"dengan pelebaran interval {100*(calibrated.AvgWidth/raw.AvgWidth-1):.2f}%. "
                   f"Sebanyak {run['n']-run['covered_n']} target tetap di luar interval akhir.")
        crossing = run['calibration']['crossing_counts']
        st.caption(f"Kuantil bersilangan sebelum pengurutan: FULL {crossing['FULL']['test']}, "
                   f"tanpa HMM {crossing['Tanpa_HMM']['test']}, dan tanpa interaksi "
                   f"{crossing['Tanpa_interaksi']['test']} pada data uji. "
                   'Semua varian tidak memiliki crossing kalibrasi atau interval kosong pada data uji.')
        with st.expander('Simulasi keterlambatan data on-chain'):
            stale = pd.DataFrame(run['stale_by_cutoff'])
            rows = []
            for window in sorted(stale.window.unique()):
                current = stale[stale.window.eq(window)].set_index('scenario')
                true, delayed = current.loc['TRUE'], current.loc['STALE']
                rows.append({'Jendela': window, 'Cutoff': str(true.cutoff),
                    'MAE TRUE (USD)': f'${true.MAE_USD:,.2f}', 'MAE STALE (USD)': f'${delayed.MAE_USD:,.2f}',
                    'Δ MAE STALE − TRUE (USD)': f'${delayed.MAE_USD-true.MAE_USD:+,.2f}',
                    'Coverage TRUE': f'{true.coverage_pct:.2f}%', 'Coverage STALE': f'{delayed.coverage_pct:.2f}%'})
            render_table(pd.DataFrame(rows), label='Simulasi 88 hari pada empat jendela uji Colab')
            st.caption('TRUE memakai netflow riil; STALE membekukannya pada nilai terakhir di cutoff. '
                       'Empat jendela masing-masing 88 hari mencakup 352 tanggal target unik. '
                       'MAE meningkat pada jendela 1–2 dan sedikit menurun pada jendela 3–4. '
                       'Pada jendela keempat, coverage kedua skenario masih di bawah nominal 90%. '
                       'Simulasi bersifat deskriptif dan belum membuktikan keamanan forward-fill secara umum.')


