# Included verbatim in the standalone dashboard; no companion import required.
def _qa_active():
    return bool(st.session_state.get('qa_authorized', False))


def _qa_event(event):
    if _qa_active():
        st.session_state.setdefault('qa_events', []).append(event)


def _qa_resources():
    """Process measurements only; never label these as host/server capacity."""
    value = {'process_cpu_seconds': time.process_time(), 'rss_bytes': None}
    try:
        import psutil
        process = psutil.Process()
        value['rss_bytes'] = process.memory_info().rss
        value['rss_method'] = 'psutil_process_current'
        value['threads'] = process.num_threads()
    except (ImportError, OSError):
        try:
            value['rss_bytes'] = int(Path('/proc/self/statm').read_text().split()[1]) * os.sysconf('SC_PAGE_SIZE')
            value['rss_method'] = 'linux_proc_current'
        except (OSError, ValueError, AttributeError):
            value['rss_method'] = 'unavailable'
    return value


def _qa_cache_body(name):
    if _qa_active():
        stack = st.session_state.get('qa_call_stack', [])
        if stack:
            st.session_state.setdefault('qa_computed', []).append(stack[-1])


def _qa_cached_call(name, function, *args):
    if not _qa_active():
        return function(*args)
    call_id = uuid.uuid4().hex
    st.session_state.setdefault('qa_call_stack', []).append(call_id)
    before = _qa_resources(); started = time.perf_counter(); error = None
    try:
        return function(*args)
    except Exception as exc:
        error = type(exc).__name__
        raise
    finally:
        after = _qa_resources()
        st.session_state.qa_call_stack.pop()
        computed = call_id in st.session_state.get('qa_computed', [])
        _qa_event({'kind':'cache_call', 'function':name, 'call_id':call_id,
                   'cache_status':'miss_computed' if computed else 'reuse_or_wait',
                   'body_executed_here':computed, 'wall_seconds':time.perf_counter()-started,
                   'process_cpu_delta_seconds':after['process_cpu_seconds']-before['process_cpu_seconds'],
                   'process_before':before, 'process_after':after, 'error_type':error})


def _qa_source(frame, source, started, response=None):
    stamp={'source':source, 'execution_id':uuid.uuid4().hex,
           'completed_utc':datetime.now(timezone.utc).isoformat(),
           'wall_seconds':time.perf_counter()-started, 'rows':len(frame),
           'first_date':str(frame.index.min()), 'last_date':str(frame.index.max()),
           'columns':list(frame.columns),
           'frame_sha256':hashlib.sha256(pd.util.hash_pandas_object(frame,index=True).values.tobytes()).hexdigest()}
    if response is not None:
        # Only fixed public endpoints are used; omit query strings, bodies and headers carrying credentials.
        stamp.update(endpoint=str(response.url).split('?')[0], http_status=int(response.status_code),
                     response_sha256=hashlib.sha256(response.content).hexdigest(),
                     response_bytes=len(response.content),
                     headers={k:response.headers.get(k) for k in ['Date','Content-Type','Last-Modified','ETag']})
    else:
        stamp.update(endpoint='Yahoo Finance via yfinance.download BTC-USD 1d',http_status=None,
                     http_metadata_limit='Individual yfinance HTTP responses not intercepted.')
    if 'exchange_netflow' in frame:
        stamp['last_nonmissing_netflow_date']=str(frame.exchange_netflow.dropna().index.max())
    frame.attrs['source_metadata']=stamp
    return frame


def _qa_scope():
    return 'qa:'+st.session_state.qa_group if _qa_active() else 'public'


def _qa_clear_scope():
    scope=_qa_scope(); started=time.perf_counter()
    _cached_build_features_and_predict.clear(scope, CORE_VERSION)
    _cached_fetch_price.clear('2021-01-01',scope,CORE_VERSION)
    _cached_fetch_sentiment.clear(scope,CORE_VERSION)
    _cached_fetch_onchain.clear('2021-01-01',scope,CORE_VERSION)
    st.session_state.qa_last_clear={'scope':scope,'wall_seconds':time.perf_counter()-started,
                                  'utc':datetime.now(timezone.utc).isoformat(),'kind':'argument_scoped_cache_clear'}


def _qa_panel():
    if st.query_params.get('qa') != '1':
        st.session_state.qa_authorized=False
        return
    st.subheader('Diagnosis TA M12–M19')
    expected=''
    try:
        expected=str(st.secrets.get('TA_DIAGNOSTIC_TOKEN') or st.secrets.get('M11_TEST_TOKEN') or '')
    except Exception:
        pass
    entered=st.text_input('Token diagnosis',type='password',key='qa_password')
    st.session_state.qa_authorized=bool(len(expected)>=24 and hmac.compare_digest(entered,expected))
    if not _qa_active():
        st.info('Masukkan token diagnosis untuk membuka sesi pengukuran.')
        st.stop()
    st.session_state.setdefault('qa_group',uuid.uuid4().hex)
    group=st.text_input('Kelompok cache uji',value=st.session_state.qa_group,max_chars=64)
    if not re.fullmatch(r'[A-Za-z0-9_-]{1,64}',group):
        st.error('Kelompok cache hanya boleh memuat huruf, angka, garis bawah, dan tanda hubung.')
        st.stop()
    if group != st.session_state.qa_group:
        st.session_state.qa_group=group
        st.session_state.dashboard_started=False
        st.session_state.comparison_only=False
    st.caption('Kelompok baru memisahkan cache aplikasi. Kelompok sama dapat berbagi cache. '
               'Refresh membersihkan kunci kelompok ini; cache browser dan cache internal yfinance tetap terpisah.')
    st.session_state.qa_events=[]
    st.session_state.qa_computed=[]
    st.session_state.qa_call_stack=[]


def _qa_receipt(result=None, error_type=None):
    return {'build':CORE_VERSION,'source_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
            'observed_utc':datetime.now(timezone.utc).isoformat(),'scope':_qa_scope(),
            'events':st.session_state.get('qa_events',[]),
            'last_clear':st.session_state.get('qa_last_clear'),
            'process':_qa_resources(),'pipeline_success':result is not None,'error_type':error_type,
            'pipeline_metadata':result.get('pipeline_metadata') if result else None,
            'limits':['Process CPU/RSS are not host capacity; concurrent CPU attribution is shared.',
                      'RSS snapshots are not continuous peak measurement.',
                      'Cached origin timings are not new fit measurements.',
                      'reuse_or_wait includes waiting for another session to populate the cache.',
                      'Browser cache and internal yfinance cache are not application cache.']}


def _qa_show_receipt(result=None,error_type=None):
    if _qa_active():
        receipt=_qa_receipt(result,error_type)
        st.json(receipt,expanded=False)
        st.download_button('Unduh bukti diagnosis',json.dumps(receipt,ensure_ascii=False,indent=2),
                           file_name='diagnosis_ta.json',mime='application/json')
        if result is not None:
            audit={'metadata':result['pipeline_metadata'],
                   'df_csv':result['df'][['close','polarity','exchange_netflow','regime_labeled']].to_csv(),
                   'forecast':{k:([str(v) for v in result[k]] if k=='hist_target_dates' else
                                    np.asarray(result[k]).tolist() if k.startswith('hist_') else
                                    str(result[k]) if k in ['pred_date','onchain_last_real_date'] else result[k])
                               for k in ['hist_target_dates','hist_true','hist_med','hist_lo','hist_hi',
                                         'pred_date','pred_med','pred_lo','pred_hi','onchain_last_real_date']},
                   'metrics':load_experiments()['runs']['colab_latest']['metrics']}
            st.download_button('Unduh data audit grafik',json.dumps(audit,ensure_ascii=False),
                               file_name='data_audit_grafik.json',mime='application/json')


def _source_cache_paths(kind, scope):
    if kind not in ['price','sentiment','onchain']:
        raise ValueError('Sumber cache tidak dikenal.')
    key = hashlib.sha256(f'{CORE_VERSION}:{scope}'.encode('utf-8')).hexdigest()[:20]
    root = Path(__file__).resolve().parent/'.cache'/'real_sources'
    return root/f'{kind}_{key}.csv', root/f'{kind}_{key}.json'


def _remember_source(frame, kind, scope):
    """Persist successful real observations; failure to write must not hide valid data."""
    frame.attrs['source_metadata'].update(storage_kind='downloaded', is_fallback=False)
    csv_path, meta_path = _source_cache_paths(kind, scope)
    try:
        csv_path.parent.mkdir(parents=True,exist_ok=True)
        raw = frame.rename_axis('date').to_csv().encode('utf-8')
        metadata = dict(frame.attrs['source_metadata'], csv_sha256=hashlib.sha256(raw).hexdigest())
        token = uuid.uuid4().hex
        csv_tmp = csv_path.with_name(csv_path.name+f'.{token}.tmp')
        meta_tmp = meta_path.with_name(meta_path.name+f'.{token}.tmp')
        csv_tmp.write_bytes(raw)
        meta_tmp.write_text(json.dumps(metadata,ensure_ascii=False),encoding='utf-8')
        os.replace(csv_tmp,csv_path)
        os.replace(meta_tmp,meta_path)
    except OSError:
        pass
    return frame


def _read_source_csv(raw, kind):
    frame = pd.read_csv(io.StringIO(raw),float_precision='round_trip')
    if 'date' not in frame:
        raise ValueError('Snapshot tidak mempunyai tanggal.')
    dates = pd.to_datetime(frame.pop('date'),errors='raise')
    frame.index = pd.DatetimeIndex(dates,name='date')
    required = {'price':['open','high','low','close','volume'],
                'sentiment':['value','value_classification','polarity'],
                'onchain':['FlowInExNtv','FlowOutExNtv','exchange_netflow']}[kind]
    if (frame.empty or not set(required).issubset(frame.columns) or not frame.index.is_unique
            or not frame.index.is_monotonic_increasing or frame.index.tz is not None
            or (frame.index != frame.index.normalize()).any()):
        raise ValueError('Snapshot sumber tidak valid.')
    for column in [c for c in required if c != 'value_classification']:
        frame[column] = pd.to_numeric(frame[column],errors='raise')
        if not np.isfinite(frame[column].dropna().to_numpy()).all():
            raise ValueError('Angka snapshot tidak valid.')
    return frame


def _stored_source(kind, scope, error):
    """Use a previously downloaded real snapshot; never synthesize observations."""
    csv_path, meta_path = _source_cache_paths(kind, scope)
    try:
        raw = csv_path.read_bytes()
        metadata = json.loads(meta_path.read_text(encoding='utf-8'))
        if hashlib.sha256(raw).hexdigest() != metadata['csv_sha256']:
            raise ValueError('Checksum snapshot berubah.')
        frame = _read_source_csv(raw.decode('utf-8'),kind)
        storage = 'saved_real_snapshot'
    except (OSError,ValueError,KeyError,TypeError):
        snapshot = load_experiments()['snapshots'][kind]
        frame = _read_source_csv(snapshot['csv'],kind)
        metadata = dict(source={'price':'price_yfinance','sentiment':'sentiment_alternative_me',
                                'onchain':'onchain_community_csv'}[kind],
            completed_utc=snapshot['downloaded_utc'], snapshot_original_sha256=snapshot['original_sha256'],
            endpoint=snapshot['source_url'], rows=len(frame), first_date=str(frame.index.min()),
            last_date=str(frame.index.max()), columns=list(frame.columns), reference_run_id=snapshot['run_id'])
        storage = 'embedded_real_ta_snapshot'
    metadata.update(storage_kind=storage,is_fallback=True,fallback_reason=type(error).__name__)
    frame.attrs['source_metadata'] = metadata
    return frame


@st.cache_data(ttl=3600)
def _cached_fetch_price(start="2021-01-01", cache_scope="public", reference_version=CORE_VERSION):
    _qa_cache_body("price")
    source_started = time.perf_counter()
    import yfinance as yf
    cache_dir = Path(__file__).resolve().parent / ".cache" / "yfinance"
    cache_dir.mkdir(parents=True, exist_ok=True)
    yf.set_tz_cache_location(str(cache_dir))
    df = yf.download("BTC-USD", start=start, interval="1d", progress=False)
    if df.empty:
        raise RuntimeError("Yahoo Finance tidak mengembalikan data BTC-USD")
    if isinstance(df.columns, pd.MultiIndex):
        df.columns = df.columns.get_level_values(0)
    df = df.reset_index()
    date_col = "Date" if "Date" in df.columns else df.columns[0]
    df["date"] = pd.to_datetime(df[date_col])
    if df["date"].dt.tz is not None:
        df["date"] = df["date"].dt.tz_localize(None)
    df = df[["date","Open","High","Low","Close","Volume"]].set_index("date")
    df.columns = ["open","high","low","close","volume"]
    df = df.dropna()

    today_utc = pd.Timestamp(datetime.now(timezone.utc).date())
    df = df[df.index < today_utc]  # buang baris "hari ini" (live/belum final)
    if df.empty:
        raise RuntimeError('Tidak ada harga penutupan harian yang sudah selesai.')
    return _remember_source(_qa_source(df, 'price_yfinance', source_started), 'price', cache_scope)


def fetch_price(start="2021-01-01", cache_scope="public"):
    try:
        return _qa_cached_call('price',_cached_fetch_price,start,cache_scope,CORE_VERSION)
    except (RuntimeError,ValueError,OSError,requests.RequestException):
        error = RuntimeError('Sumber harga tidak tersedia.')
        frame = _stored_source('price',cache_scope,error)
        return frame.loc[start:].copy()


def _source_records(payload):
    """Accept a nonempty record list, not an API error masquerading as data."""
    if not isinstance(payload, dict):
        raise ValueError("Struktur respons sumber tidak valid.")
    metadata = payload.get("metadata")
    if isinstance(metadata, dict) and metadata.get("error"):
        raise ValueError("Sumber melaporkan kegagalan data.")
    records = payload.get("data")
    if not isinstance(records, list) or not records or not all(isinstance(row, dict) for row in records):
        raise ValueError("Daftar observasi sumber kosong atau tidak valid.")
    return records


def _validate_onchain(frame, start):
    """Preserve missing historical flows; reject malformed or unusable data."""
    columns = ["time", "FlowInExNtv", "FlowOutExNtv"]
    if frame.empty or not set(columns).issubset(frame.columns):
        raise ValueError("Kolom on-chain tidak lengkap.")
    frame = frame[columns].copy()
    dates = pd.to_datetime(frame.pop("time"), errors="coerce", utc=True, format="mixed")
    if dates.isna().any() or (dates != dates.dt.normalize()).any() or dates.duplicated().any():
        raise ValueError("Tanggal on-chain tidak valid atau berulang.")
    frame.index = pd.DatetimeIndex(dates.dt.tz_localize(None), name="time")
    for col in ["FlowInExNtv", "FlowOutExNtv"]:
        raw = frame[col]
        missing = raw.isna() | raw.astype(str).str.strip().eq("")
        numeric = pd.to_numeric(raw, errors="coerce")
        if ((~missing & numeric.isna()).any()
                or (~np.isfinite(numeric.dropna().to_numpy(dtype=float))).any()
                or numeric.dropna().lt(0).any()
                or raw.map(lambda value: isinstance(value, (bool, np.bool_))).any()):
            raise ValueError("Nilai arus on-chain tidak valid.")
        frame[col] = numeric
    frame["exchange_netflow"] = frame["FlowOutExNtv"] - frame["FlowInExNtv"]
    frame = frame.sort_index().loc[start:]
    observed = frame["exchange_netflow"].dropna()
    if observed.empty or not np.isfinite(observed.to_numpy(dtype=float)).all():
        raise ValueError("Observasi netflow valid tidak tersedia pada rentang yang diminta.")
    return frame[["exchange_netflow", "FlowInExNtv", "FlowOutExNtv"]]


@st.cache_data(ttl=3600)
def _cached_fetch_sentiment(cache_scope="public", reference_version=CORE_VERSION):
    _qa_cache_body("sentiment")
    source_started = time.perf_counter()
    try:
        r = requests.get("https://api.alternative.me/fng/?limit=0", timeout=15)
        r.raise_for_status()
        df = pd.DataFrame(_source_records(r.json()))
        columns = ["timestamp", "value", "value_classification"]
        if not set(columns).issubset(df.columns):
            raise ValueError("Kolom sentimen tidak lengkap.")
        timestamps = pd.to_numeric(df["timestamp"], errors="coerce")
        values = pd.to_numeric(df["value"], errors="coerce")
        for numeric in [timestamps, values]:
            if numeric.isna().any() or not np.isfinite(numeric.to_numpy(dtype=float)).all():
                raise ValueError("Angka sentimen tidak valid.")
        if (timestamps.le(0).any() or timestamps.mod(1).ne(0).any()
                or not values.between(0, 100).all() or values.mod(1).ne(0).any()
                or df[["timestamp", "value"]].map(lambda value: isinstance(value, (bool, np.bool_))).any().any()):
            raise ValueError("Rentang angka sentimen tidak valid.")
        dates = pd.to_datetime(timestamps, unit="s", utc=True, errors="coerce")
        if dates.isna().any() or dates.dt.normalize().duplicated().any():
            raise ValueError("Tanggal sentimen tidak valid atau berulang.")
        if not df["value_classification"].map(lambda value: isinstance(value, str) and bool(value.strip())).all():
            raise ValueError("Label sentimen tidak valid.")
        df["date"] = dates.dt.normalize().dt.tz_localize(None)
        df["value"] = values.astype(int)
        df = df[["date", "value", "value_classification"]].set_index("date").sort_index()
        mapping = {"Extreme Fear":-1,"Fear":-0.5,"Neutral":0,"Greed":0.5,"Extreme Greed":1}
        df["polarity"] = df["value_classification"].map(mapping)
        df["polarity"] = df["polarity"].fillna((df["value"]-50)/50)
        return _remember_source(_qa_source(df, 'sentiment_alternative_me', source_started, r),
                                'sentiment',cache_scope), True
    except (requests.RequestException, ValueError, TypeError, KeyError, OverflowError):
        # Raising prevents cache_data from storing a failed response for an hour.
        # Keep URLs, credentials and response bodies out of user-facing errors.
        raise RuntimeError("Sentimen riil tidak tersedia atau tidak valid. Prediksi tidak dijalankan.") from None

def fetch_sentiment(cache_scope="public"):
    try:
        return _qa_cached_call('sentiment',_cached_fetch_sentiment,cache_scope,CORE_VERSION)
    except (RuntimeError,ValueError,OSError,requests.RequestException) as error:
        return _stored_source('sentiment',cache_scope,error),True

@st.cache_data(ttl=3600)
def _cached_fetch_onchain(start="2021-01-01", cache_scope="public", reference_version=CORE_VERSION):
    _qa_cache_body("onchain")
    source_started = time.perf_counter()
    # Use only the free CoinMetrics Community CSV source.
    url = "https://raw.githubusercontent.com/coinmetrics/data/master/csv/btc.csv"
    try:
        r = requests.get(url, timeout=30)
        r.raise_for_status()
        df = pd.read_csv(io.StringIO(r.text), low_memory=False)
        return _remember_source(_qa_source(_validate_onchain(df,start),'onchain_community_csv',source_started,r),
                                'onchain',cache_scope),False
    except (requests.RequestException, ValueError, TypeError, KeyError, OverflowError):
        raise RuntimeError("Data on-chain tidak tersedia atau tidak valid. Prediksi tidak dijalankan.") from None

